// ===========================================
// CONFIGURATION - Edit these values directly
// ===========================================
const CONFIG = {
  // Slack Webhook URL - Get from Slack App settings
  // Leave empty to disable Slack notifications
  SLACK_WEBHOOK_URL: '',

  // Qdrant Vector DB - Set URL and API key to enable
  // Leave empty to skip vectorization
  QDRANT_URL: 'http://qdrant:6333',  // Docker service name
  QDRANT_API_KEY: '',

  // Gemini API for embeddings (768 dimensions)
  GEMINI_API_KEY: '<REDACTED:google-api-key>',

  // Feature flags
  ENABLE_SLACK: false,
  ENABLE_QDRANT: true,
  ENABLE_CRM: false,  // Disabled - no Pipedrive yet

  // Debug mode - logs extra info
  DEBUG: true
};

// Parse the incoming payload
const payload = $json.body || $json;
const processing_id = 'proc_' + Date.now() + '_' + Math.random().toString(36).substr(2,9);

// Validate required fields
const requiredFields = {
  'type': payload.type,
  'data': payload.data,
  'data.conversation_id': payload.data?.conversation_id
};

const missingFields = [];
for (const [field, value] of Object.entries(requiredFields)) {
  if (value === undefined || value === null || value === '') {
    missingFields.push(field);
  }
}

if (missingFields.length > 0) {
  return {
    json: {
      config: CONFIG,
      valid: false,
      error: 'SCHEMA_VALIDATION_FAILED',
      missing_fields: missingFields,
      event_type: payload.type || 'undefined',
      processing_id
    }
  };
}

// Extract and normalize all fields
const data = payload.data;
const clientData = data.conversation_initiation_client_data || {};
const dynamicVars = clientData.dynamic_variables || {};
const analysis = data.analysis || {};
const metadata = data.metadata || {};
const dataCollection = analysis.data_collection_results || {};

const transcript = data.transcript || [];
const transcript_text = transcript.map(t => t.role + ': ' + t.message).join('\n');

return {
  json: {
    config: CONFIG,
    valid: true,
    processing_id,
    event_type: payload.type,
    conversation_id: data.conversation_id,
    agent_id: data.agent_id || '',
    pipedrive_person_id: dynamicVars.pipedrive_person_id || null,
    customer_name: dynamicVars.customer_name || '',
    customer_phone: dynamicVars.phone || metadata.caller_phone || '',
    call_duration_secs: metadata.call_duration_secs || 0,
    start_time_unix: metadata.start_time_unix_secs || 0,
    call_successful: analysis.call_successful || 'unknown',
    transcript_summary: analysis.transcript_summary || '',
    budget: dataCollection.budget || dataCollection.Budget || 'not_discussed',
    timeline: dataCollection.timeline || dataCollection.Timeline || 'not_discussed',
    authority: dataCollection.authority || dataCollection.Authority || 'not_discussed',
    need: dataCollection.need || dataCollection.Need || 'not_discussed',
    transcript,
    transcript_text,
    transcript_available: transcript.length > 0,
    failure_reason: data.failure_reason || null,
    received_at: new Date().toISOString()
  }
};

const data = $json;
const qualificationStatus = data.call_successful === 'success' ? 'qualified' : data.call_successful === 'failure' ? 'not_qualified' : 'needs_review';
const qualificationScore = data.call_successful === 'success' ? 80 : data.call_successful === 'failure' ? 20 : 50;
const noteContent = `## AI Qualification Call Summary

**Status:** ${qualificationStatus}
**Score:** ${qualificationScore}/100
**Duration:** ${Math.round((data.call_duration_secs || 0) / 60)} minutes

### Summary
${data.transcript_summary || 'No summary available'}

### BANT
- Budget: ${data.budget}
- Timeline: ${data.timeline}
- Authority: ${data.authority}
- Need: ${data.need}

---
*Conversation ID: ${data.conversation_id}*`;
const crmLabel = qualificationStatus === 'qualified' ? 'Hot Lead' : qualificationStatus === 'not_qualified' ? 'Cold' : 'Warm Lead';
return { json: { ...data, crm_note_content: noteContent, crm_label: crmLabel, crm_qualification_status: qualificationStatus } };

const items = $input.all();
const firstItem = items[0]?.json || {};

// Aggregate results from all branches
const result = {
  processing_id: firstItem.processing_id || 'unknown',
  conversation_id: firstItem.conversation_id || 'unknown',
  event_type: firstItem.event_type || 'unknown',
  completed_at: new Date().toISOString(),

  // Status flags
  slack_notified: items.some(i => i.json?.ok || i.json?.attachments),
  crm_updated: items.some(i => i.json?.id && i.json?.content),
  vector_stored: items.some(i => i.json?.result?.operation_id || i.json?.status === 'ok' || i.json?.result?.status === 'completed'),

  // Config status
  config_slack_enabled: firstItem.config?.ENABLE_SLACK || false,
  config_qdrant_enabled: firstItem.config?.ENABLE_QDRANT || false,
  config_crm_enabled: firstItem.config?.ENABLE_CRM || false,

  // Collect any errors
  errors: items
    .filter(i => i.json?.error || i.json?.errorCode || i.json?.crm_skip_reason || i.json?.vector_skip_reason)
    .map(i => ({
      type: i.json?.crm_skip_reason ? 'crm_skipped' : i.json?.vector_skip_reason ? 'vector_skipped' : 'error',
      message: i.json?.error || i.json?.errorCode || i.json?.crm_skip_reason || i.json?.vector_skip_reason || i.json?.message
    })),

  items_processed: items.length
};

result.overall_success = result.errors.filter(e => e.type === 'error').length === 0;

return [{ json: result }];

const item = $input.first().json;
const headers = item.headers || {};
const sigHeader = headers['elevenlabs-signature'] || headers['ElevenLabs-Signature'] || '';
const parts = Object.fromEntries(sigHeader.split(',').map(p => { const i = p.indexOf('='); return [p.slice(0,i).trim(), p.slice(i+1).trim()]; }));
const t = parts.t || '';
const v0 = parts.v0 || '';
const ageSec = t ? Math.abs(Math.floor(Date.now() / 1000) - Number(t)) : null;
const stale = !t || !v0 || !Number.isFinite(ageSec) || ageSec > 60 * 30;
const body = JSON.stringify(item.body ?? {});
return [{ json: { ...item, _hmac_t: t, _hmac_v0: v0, _hmac_payload: t + '.' + body, _hmac_stale: stale, _hmac_age: ageSec } }];

const d = $input.item.json;
const transcript = d.transcript_text || '';
if (!transcript || transcript.length < 20) {
  return { json: { ...d, _extraction_skip: true, _extraction_skip_reason: 'transcript too short' } };
}
return {
  json: {
    ...d,
    _extraction_skip: false,
    skip: false,
    transcript: transcript,
    agent_system_prompt: 'You are Sarah, a sales development representative for Wranngle Systems. You qualify leads for The 24/7 Filter — an AI-powered after-hours call answering service for SMBs (HVAC, plumbing, property management, legal).',
    extraction_config: {
      categories: [
        { category_id: 'sales', context_rules: { default_strictness: 'medium', require_rationale: true, null_behavior: 'return_null_with_rationale' }, fields: [
          { field_id: 'deal_stage', type: 'enum', values: ['discovery','qualification','proposal','negotiation','closed_won','closed_lost'], required: true, default_value: 'discovery', prompt: 'Stage of sales process. Did the caller express need? Mention budget/timeline?', strictness: 'high' },
          { field_id: 'budget_mentioned', type: 'string', required: false, prompt: 'Any budget, price range, financial constraints mentioned. Include exact figures.', strictness: 'medium' },
          { field_id: 'decision_authority', type: 'enum', values: ['caller','other','unknown'], required: true, default_value: 'unknown', prompt: 'Does the caller have decision authority?', strictness: 'medium' },
          { field_id: 'timeline', type: 'string', required: false, prompt: 'Any timeline / deadline / urgency mentioned.', strictness: 'medium' },
          { field_id: 'next_steps', type: 'string', required: false, prompt: 'Next steps discussed or agreed.', strictness: 'low' },
          { field_id: 'qualification_status', type: 'enum', values: ['qualified','not_qualified','needs_review'], required: true, default_value: 'needs_review', prompt: 'Qualified = expressed need + budget or timeline. Not qualified = no interest, wrong number, spam.', strictness: 'medium' },
          { field_id: 'transcript_summary', type: 'string', required: true, default_value: 'No summary available', prompt: 'Concise 2-3 sentence summary: who called, what they wanted, outcome.', strictness: 'low' }
        ] },
        { category_id: 'support', context_rules: { default_strictness: 'medium', require_rationale: true, null_behavior: 'return_null_with_rationale' }, fields: [
          { field_id: 'issue_type', type: 'string', required: true, prompt: 'What type of issue or request is the caller reporting? Categorize briefly.', strictness: 'medium' },
          { field_id: 'urgency', type: 'enum', values: ['emergency','soon','routine','estimate'], required: true, default_value: 'routine', prompt: 'How urgent: emergency = safety/critical down. soon = quick attention. routine = standard. estimate = quote/info only.', strictness: 'high' },
          { field_id: 'resolution_status', type: 'enum', values: ['resolved','unresolved','escalated'], required: true, default_value: 'unresolved', prompt: 'Was the issue resolved during the call, left unresolved, or escalated?', strictness: 'high' },
          { field_id: 'escalation_needed', type: 'boolean', required: true, default_value: false, prompt: 'Does this call require escalation to a human agent or specialist?', strictness: 'high' },
          { field_id: 'existing_request', type: 'boolean', required: true, default_value: false, prompt: 'Is this regarding an existing request/ticket? Detection: case/ticket numbers, "following up on", "checking status of". Default FALSE when unclear.', strictness: 'high' },
          { field_id: 'request_affected_asset', type: 'string', required: false, prompt: 'Specific equipment, device, software, or system involved. Include model numbers, asset IDs if stated. Null when none.', strictness: 'medium' },
          { field_id: 'request_deadline', type: 'string', required: false, prompt: 'Requestor-specified date or timeframe. Examples: "fixed by Friday", "within 48 hours". Null when none.', strictness: 'medium' },
          { field_id: 'request_description', type: 'string', required: false, prompt: 'Single factual paragraph (80-120 words) using ONLY explicitly stated information. Inverted-pyramid. Plain language, active voice. No future commitments.', strictness: 'low' },
          { field_id: 'request_summary', type: 'string', required: false, prompt: 'Precise ticket title (<80 chars). Format: "[Equipment/Issue] - [Location]". Avoid generic terms. Include equipment ID if provided.', strictness: 'medium' }
        ] },
        { category_id: 'external_contacts', context_rules: { default_strictness: 'high', require_rationale: false, null_behavior: 'return_null_with_rationale' }, fields: [
          { field_id: 'requestor_first_name', type: 'string', required: false, prompt: 'First name from self-introduction. Extract ONLY first name. Null if none.', strictness: 'high' },
          { field_id: 'requestor_last_name', type: 'string', required: false, prompt: 'Last name only. Capture compound surnames completely (e.g., "De La Vega"). Null if none.', strictness: 'high' },
          { field_id: 'requestor_company_name', type: 'string', required: false, prompt: 'Caller employer/company from "I am with / calling from / I work for". Never extract service-provider name from agent greeting. Ignore the company being called.', strictness: 'medium' },
          { field_id: 'contact_phone', type: 'phone', required: false, prompt: 'Final confirmed callback phone in E.164 (+1XXXXXXXXXX). If user corrected a number, use correction only. Null if <10 digits.', strictness: 'high' },
          { field_id: 'contact_email', type: 'email', required: false, prompt: 'Email caller provides.', strictness: 'high' },
          { field_id: 'contact_preferred_followup_channel', type: 'enum', values: ['phone','sms','email'], required: false, default_value: 'phone', prompt: 'Default phone when unclear. Triggers: "call me", "text me", "send me an email".', strictness: 'medium' },
          { field_id: 'contact_preferred_followup_time', type: 'string', required: false, prompt: 'Follow-up timing preferences. Examples: "tomorrow afternoon", "after 6 PM only". Null when none.', strictness: 'medium' },
          { field_id: 'requested_service_address', type: 'string', required: false, prompt: 'Physical location WHERE WORK HAPPENS (dispatch destination). NOT the branch being contacted. Null if no dispatch required.', strictness: 'medium' },
          { field_id: 'requestor_is_contact', type: 'boolean', required: true, default_value: true, prompt: 'Is requestor the designated contact for follow-up? Default TRUE; FALSE only if explicit alternate contact named.', strictness: 'high' }
        ] },
        { category_id: 'internal_contacts', context_rules: { default_strictness: 'medium', require_rationale: false, null_behavior: 'return_null_with_rationale' }, fields: [
          { field_id: 'requested_person', type: 'string', required: false, prompt: 'Name of specific person requestor asks to speak with. Null if no specific person requested by name.', strictness: 'high' },
          { field_id: 'department', type: 'enum', values: ['Service','Field Service','Sales','Marketing','Purchasing','Fulfillment','Shipping','Billing','Finance','Accounting','HR','Payroll','IT','IT Support','Operations','Contracts','Administration','General'], required: true, default_value: 'General', prompt: 'EXACTLY one from allowed values. Default General when unclear.', strictness: 'high' },
          { field_id: 'transfer_reason', type: 'string', required: false, prompt: 'Short summary (<=120 chars) explaining WHY transferred. Null if no transfer.', strictness: 'low' },
          { field_id: 'conversation_transferred', type: 'boolean', required: true, default_value: false, prompt: 'Was conversation transferred to live person? TRUE only when actual transfer mechanism invoked. Default FALSE.', strictness: 'high' },
          { field_id: 'transfer_destination', type: 'string', required: false, prompt: 'If transferred, capture destination label. Examples: "Main operator", "Billing department". Null if no transfer.', strictness: 'medium' }
        ] },
        { category_id: 'external_company', context_rules: { default_strictness: 'medium', require_rationale: false, null_behavior: 'return_null_with_rationale' }, fields: [
          { field_id: 'company_industry', type: 'string', required: false, prompt: 'Industry the caller\'s company operates in.', strictness: 'medium' },
          { field_id: 'company_size', type: 'string', required: false, prompt: 'Any mention of company size (employees, revenue, locations).', strictness: 'medium' },
          { field_id: 'company_location', type: 'string', required: false, prompt: 'Caller\'s company location (city, state, region).', strictness: 'medium' }
        ] },
        { category_id: 'internal_company', context_rules: { default_strictness: 'medium', require_rationale: false, null_behavior: 'return_null_with_rationale' }, fields: [
          { field_id: 'site_location', type: 'string', required: false, prompt: 'Site or branch location for internal routing. Null if none mentioned.', strictness: 'medium' },
          { field_id: 'service_area', type: 'string', required: false, prompt: 'Service area or product line this call relates to.', strictness: 'medium' },
          { field_id: 'account_status', type: 'enum', values: ['active','inactive','prospect','churned'], required: true, default_value: 'prospect', prompt: 'Caller\'s account status: existing customer, prospect, or former.', strictness: 'high' }
        ] }
      ],
      global_context: { agent_identity: 'Sarah - Wranngle Lead Specialist', business_domain: 'AI-powered after-hours call answering for SMBs' }
    },
    metadata: { conversation_id: d.conversation_id, agent_id: d.agent_id }
  }
};

const items = $input.all();
const out = [];
for (const it of items) {
  const input = it.json || {};
  const fields = input.fields || [];
  const meta = {
    extraction_id: input.extraction_id || '',
    conversation_id: input.conversation_id || '',
    timestamp: input.timestamp || new Date().toISOString(),
    model: input.model || '',
    categories_processed: input.categories_processed || 0,
    errors_count: (input.errors || []).length,
  };
  const row = { ...meta };
  for (const f of fields) {
    const key = (f.category || 'unknown') + '__' + (f.field_id || 'unknown');
    row[key] = String(f.value ?? '');
  }
  row.raw_envelope = JSON.stringify(input);
  out.push({ json: row });
}
return out;

