={{ JSON.stringify((function() {
  // Pipedrive Person UPDATE body. Pulls qualification context from
  // upstream "Prep CRM Data" so updates carry meaningful tags rather
  // than just visibility.
  //
  // To enable auto-labeling, set the operator-specific Pipedrive label
  // IDs via n8n env vars (Settings -> Variables):
  //   PIPEDRIVE_LABEL_HOT  = id of "Hot Lead" label
  //   PIPEDRIVE_LABEL_WARM = id of "Warm Lead" label
  //   PIPEDRIVE_LABEL_COLD = id of "Cold" label
  //
  // Without those vars set, the body falls back to visible_to=3 only
  // (no destructive overwrite of name/phone/email arrays).
  const body = { visible_to: 3 };
  const label = $json.crm_label;
  const labelMap = {
    'Hot Lead':  $env.PIPEDRIVE_LABEL_HOT,
    'Warm Lead': $env.PIPEDRIVE_LABEL_WARM,
    'Cold':      $env.PIPEDRIVE_LABEL_COLD,
  };
  const labelId = label && labelMap[label];
  if (labelId) body.label_ids = [parseInt(labelId, 10)];
  return body;
})()) }}

