const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const data = body.data || body;
const signature = headers['elevenlabs-signature'] || headers['ElevenLabs-Signature'] || '';
const ip = headers['cf-connecting-ip'] || headers['x-forwarded-for'] || headers['CF-Connecting-IP'] || 'unknown';
const conversationId = data.conversation_id || data.conversation?.id || body.conversation_id || 'unknown';
const eventType = body.type || body.event_type || data.type || data.event_type || 'unknown';
const callId = data.call_id || data.call?.id || body.call_id || 'unknown';
const now = Date.now();
const windowMs = 15 * 60 * 1000;
const maxPerWindow = 10;
const dedupeMs = 24 * 60 * 60 * 1000;
function normalize(value) { return String(value ?? '').trim().toLowerCase().replace(/\s+/g, ' '); }
function hash(value) { let result = 0; for (const character of String(value)) { result = (result * 31 + character.codePointAt(0)) % Number.MAX_SAFE_INTEGER; } return result.toString(36); }
const staticData = $getWorkflowStaticData('global');
staticData.postCallGuard = staticData.postCallGuard || { rate: {}, dedupe: {} };
const guard = staticData.postCallGuard;
let cleaned = 0;
for (const [key, record] of Object.entries(guard.rate)) { if (cleaned >= 50) break; if (!record || record.resetAt <= now) { delete guard.rate[key]; cleaned++; } }
cleaned = 0;
for (const [key, expiresAt] of Object.entries(guard.dedupe)) { if (cleaned >= 50) break; if (expiresAt <= now) { delete guard.dedupe[key]; cleaned++; } }
const principal = hash([ip, signature.slice(0, 80), conversationId].map(normalize).join('|'));
const rate = guard.rate[principal] || { count: 0, resetAt: now + windowMs };
if (rate.resetAt <= now) { rate.count = 0; rate.resetAt = now + windowMs; }
rate.count++;
guard.rate[principal] = rate;
const dedupeKey = hash([signature, conversationId, eventType, callId].map(normalize).join('|'));
const duplicate = Boolean(guard.dedupe[dedupeKey]);
const rateLimited = rate.count > maxPerWindow;
if (!duplicate) { guard.dedupe[dedupeKey] = now + dedupeMs; }
const allowed = !duplicate && !rateLimited;
return [{ json: { ...item, _post_call_guard: { allowed, duplicate, rateLimited, reason: allowed ? 'allowed' : duplicate ? 'duplicate' : 'rate_limited', count: rate.count, limit: maxPerWindow, resetAt: new Date(rate.resetAt).toISOString() } } }];
